import * as THREE from 'three';

const canvas = document.querySelector('#scene');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x101a2a);
scene.fog = new THREE.Fog(0x101a2a, 95, 430);
const camera = new THREE.PerspectiveCamera(62, innerWidth / innerHeight, 0.1, 900);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.18;

const ui = Object.fromEntries(['hud','intro','pauseScreen','playBtn','pauseBtn','mobilePause','resumeBtn','loading','speed','speedFill','gear','progressFill','progressText','missionTitle','missionCopy','money','toast','stars','streetName','distance'].map(id => [id, document.getElementById(id)]));
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const rand = (a, b) => a + Math.random() * (b - a);
const mat = (color, roughness = 0.85, emissive = 0x000000, intensity = 0) => new THREE.MeshStandardMaterial({ color, roughness, emissive, emissiveIntensity: intensity });
const mats = {
  asphalt: mat(0x252f3c), pavement: mat(0x59616a), concrete: mat(0x303b48), sand: mat(0x8c7967), grass: mat(0x253d3b),
  white: mat(0xf2eee3, .35), glass: new THREE.MeshStandardMaterial({ color: 0x162638, metalness: .5, roughness: .23 }), rubber: mat(0x11151c),
  lime: mat(0xc9f16a, .32, 0x9aca45, .55), warm: mat(0xffc777, .35, 0xffa442, 1.8), red: mat(0xff5462, .35, 0xf52137, 1.4)
};
const boxGeo = new THREE.BoxGeometry(1, 1, 1);
function box(parent, name, size, position, material, rotationY = 0) {
  const mesh = new THREE.Mesh(boxGeo, material);
  mesh.name = name; mesh.scale.set(...size); mesh.position.set(...position); mesh.rotation.y = rotationY;
  mesh.castShadow = false; mesh.receiveShadow = true; parent.add(mesh); return mesh;
}
function cylinder(parent, radiusTop, radiusBottom, height, position, material, segments = 8) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radiusTop, radiusBottom, height, segments), material);
  mesh.position.set(...position); parent.add(mesh); return mesh;
}

scene.add(new THREE.HemisphereLight(0x91b6d0, 0x27323a, 1.35));
const moon = new THREE.DirectionalLight(0x9fc8ff, 1.75); moon.position.set(-80, 120, -40); scene.add(moon);
const cityGlow = new THREE.PointLight(0xff8a66, 75, 190, 2); cityGlow.position.set(-80, 30, -120); scene.add(cityGlow);
const ground = new THREE.Mesh(new THREE.PlaneGeometry(900, 900), mats.grass); ground.rotation.x = -Math.PI / 2; ground.position.y = -0.16; scene.add(ground);

const city = new THREE.Group(); scene.add(city);
const buildings = [];
const buildingPalette = [0x465465,0x59616b,0x343f50,0x6a6261,0x3c5260,0x776b63,0x414858,0x4f5965].map(c => mat(c));
const windowMats = [mat(0xffc985,.4,0xffa14c,1.15), mat(0xa6d7ef,.4,0x67bfe4,.75), mat(0x283444), mat(0xffdd9b,.4,0xffbd66,.8)];
const roadMat = mat(0x252b35, .97), laneMat = mat(0xd9d3bb, .8, 0x756b4b, .12);
function addRoads() {
  for (let n=-4; n<=4; n++) {
    const p = n * 50;
    box(city, 'east-west avenue', [900,.12,15], [0,-.045,p], roadMat);
    box(city, 'north-south avenue', [15,.12,900], [p,-.045,0], roadMat);
    // Broken lane markings along both directions.
    for (let k=-8; k<=8; k++) {
      box(city,'lane dash',[8,.025,.22],[k*48,.025,p],laneMat);
      box(city,'lane dash',[.22,.025,8],[p,.025,k*48],laneMat);
    }
    // Curbs and sidewalks make the street grid easy to read.
    for (const side of [-1,1]) {
      box(city,'sidewalk',[900,.18,2.1],[0,.02,p+side*9.1],mats.pavement);
      box(city,'sidewalk',[2.1,.18,900],[p+side*9.1,.02,0],mats.pavement);
    }
  }
  // Coastal promenade, beach and dark water on the south edge of the city.
  box(city,'coast boulevard',[900,.12,16],[0,-.03,231],roadMat);
  box(city,'beach',[900,.16,62],[0,-.1,270],mats.sand);
  const waterMat = new THREE.MeshStandardMaterial({color:0x102e42, roughness:.25, metalness:.18, emissive:0x082436, emissiveIntensity:.42});
  const water = new THREE.Mesh(new THREE.PlaneGeometry(1200,400), waterMat); water.rotation.x=-Math.PI/2; water.position.set(0,-.22,500); city.add(water);
  for (let x=-430;x<=430;x+=18) {
    box(city,'shore line',[10,.03,.18],[x,-.01,301],mat(0xb5b8a2,.5,0x778477,.2));
  }
}
addRoads();

const windowInstances = [];
function makeBuilding(x,z) {
  const width=rand(10,20), depth=rand(10,20), floors=Math.floor(rand(2,10)), height=floors*rand(2.6,3.8);
  const bodyMat=buildingPalette[Math.floor(Math.random()*buildingPalette.length)];
  const body=box(city,'city building',[width,height,depth],[x,height/2-.02,z],bodyMat);
  body.userData.bounds={x,z,w:width/2,d:depth/2}; buildings.push(body);
  // Rooftop lip and machinery create a distinct silhouette.
  box(city,'roof ledge',[width+0.5,.38,depth+0.5],[x,height+.12,z],buildingPalette[(buildingPalette.indexOf(bodyMat)+1)%buildingPalette.length]);
  if (height>15) box(city,'rooftop unit',[width*.38,1.1,depth*.34],[x+rand(-2,2),height+.85,z+rand(-2,2)],mats.concrete);
  // Repeated glowing windows on all four sides.
  const spacing=2.15, rows=Math.max(1,Math.floor((height-2)/2.55));
  for(let row=0;row<rows;row++) {
    const y=1.5+row*2.5;
    for(let wx=-width/2+1.15;wx<width/2-.55;wx+=spacing) {
      if(Math.random()<.16) continue;
      const wm=windowMats[Math.random()<.25?0:Math.random()<.38?1:2];
      box(city,'lit window',[.72,1.12,.08],[x+wx,y,z+depth/2+.055],wm);
      box(city,'lit window',[.72,1.12,.08],[x+wx,y,z-depth/2-.055],wm);
    }
    for(let wz=-depth/2+1.15;wz<depth/2-.55;wz+=spacing) {
      if(Math.random()<.18) continue;
      const wm=windowMats[Math.random()<.26?0:Math.random()<.38?1:2];
      box(city,'lit window',[.08,1.12,.72],[x+width/2+.055,y,z+wz],wm);
      box(city,'lit window',[.08,1.12,.72],[x-width/2-.055,y,z+wz],wm);
    }
  }
  if (Math.random()<.24) {
    const signMat=Math.random()<.5?mats.lime:mats.warm;
    box(city,'neon sign',[width*.56,1.15,.22],[x,height*.56,z+depth/2+.2],signMat);
  }
}
function palm(x,z,scale=1) {
  const trunk=cylinder(city,.28*scale,.42*scale,5.2*scale,[x,2.6*scale,z],mat(0x55483f),7);
  trunk.rotation.z=rand(-.08,.08);
  const crownY=5.1*scale;
