import * as THREE from 'three';

const $ = id => document.getElementById(id);
const ui = Object.fromEntries(['hud','intro','pauseScreen','playBtn','pauseBtn','mobilePause','resumeBtn','loading','speed','speedFill','gear','progressFill','progressText','money','toast','stars','streetName','distance'].map(id => [id, $(id)]));
const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
const rand = (min, max) => min + Math.random() * (max - min);
const material = (color, roughness = .8, emissive = 0, intensity = 0) => new THREE.MeshStandardMaterial({ color, roughness, emissive, emissiveIntensity: intensity });
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x101a2a);
scene.fog = new THREE.Fog(0x101a2a, 110, 440);
const camera = new THREE.PerspectiveCamera(62, innerWidth / innerHeight, .1, 900);
const renderer = new THREE.WebGLRenderer({ canvas: $('#scene'), antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.5));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
scene.add(new THREE.HemisphereLight(0x91b6d0, 0x27323a, 1.4));
const moon = new THREE.DirectionalLight(0x9fc8ff, 1.5); moon.position.set(-80, 120, -40); scene.add(moon);
const cityGlow = new THREE.PointLight(0xff8a66, 75, 190, 2); cityGlow.position.set(-80, 30, -120); scene.add(cityGlow);
const cube = new THREE.BoxGeometry(1, 1, 1);
function box(parent, name, size, pos, mat) {
  const mesh = new THREE.Mesh(cube, mat);
  mesh.name = name; mesh.scale.set(...size); mesh.position.set(...pos); parent.add(mesh); return mesh;
}
function cylinder(parent, top, bottom, height, pos, mat, sides = 8) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(top, bottom, height, sides), mat);
  mesh.position.set(...pos); parent.add(mesh); return mesh;
}
const mats = {
  asphalt: material(0x252b35), sidewalk: material(0x59616a), concrete: material(0x303b48), sand: material(0x8c7967), grass: material(0x253d3b),
  glass: new THREE.MeshStandardMaterial({ color: 0x162638, metalness: .5, roughness: .23 }),
  lime: material(0xc9f16a, .32, 0x9aca45, .55), warm: material(0xffc777, .4, 0xffa442, 1.1), dark: material(0x11151c)
};
const city = new THREE.Group(); scene.add(city);
const ground = new THREE.Mesh(new THREE.PlaneGeometry(900, 900), mats.grass); ground.rotation.x = -Math.PI / 2; ground.position.y = -.16; city.add(ground);
const laneMat = material(0xd9d3bb, .8, 0x756b4b, .12);
for (let n = -4; n <= 4; n++) {
  const p = n * 50;
  box(city, 'avenue', [900,.12,15], [0,-.045,p], mats.asphalt);
  box(city, 'avenue', [15,.12,900], [p,-.045,0], mats.asphalt);
  for (let k = -8; k <= 8; k++) {
    box(city, 'lane dash', [8,.025,.22], [k*48,.025,p], laneMat);
    box(city, 'lane dash', [.22,.025,8], [p,.025,k*48], laneMat);
  }
  for (const side of [-1,1]) {
    box(city, 'sidewalk', [900,.18,2.1], [0,.02,p+side*9.1], mats.sidewalk);
    box(city, 'sidewalk', [2.1,.18,900], [p+side*9.1,.02,0], mats.sidewalk);
  }
}
box(city, 'coast boulevard', [900,.12,16], [0,-.03,231], mats.asphalt);
box(city, 'beach', [900,.16,62], [0,-.1,270], mats.sand);
const water = new THREE.Mesh(new THREE.PlaneGeometry(1200,400), new THREE.MeshStandardMaterial({color:0x102e42,roughness:.25,metalness:.18,emissive:0x082436,emissiveIntensity:.42}));
water.rotation.x = -Math.PI/2; water.position.set(0,-.22,500); city.add(water);
const palette = [0x465465,0x59616b,0x343f50,0x6a6261,0x3c5260,0x776b63,0x414858,0x4f5965].map(c => material(c));
const windowMats = [material(0xffc985,.4,0xffa14c,1.15),material(0xa6d7ef,.4,0x67bfe4,.75),material(0x283444)];
const buildings = [], windowInstances = [];
function makeBuilding(x,z) {
  const w=rand(9,15), d=rand(9,15), floors=Math.floor(rand(2,10)), h=floors*rand(2.6,3.8);
  const bodyMat=palette[Math.floor(Math.random()*palette.length)];
  const body=box(city,'building',[w,h,d],[x,h/2-.02,z],bodyMat);
  body.userData.bounds={x,z,w:w/2,d:d/2}; buildings.push(body);
