const traffic=[], trafficColors=[0x59798b,0x8c4d48,0xb7b5a7,0x3c4656,0xc0a773,0x4f706b];
function makeTrafficCar(x,z,axis,direction) {
  const group=new THREE.Group(); scene.add(group);
  box(group,'body',[1.8,.56,3.8],[0,.68,0],material(trafficColors[Math.floor(Math.random()*trafficColors.length)],.38));
  box(group,'cabin',[1.4,.62,1.7],[0,1.2,.05],mats.glass);
  for(const side of [-1,1]) for(const zz of [-1.25,1.25]) { const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.34,.34,.23,10),tireMat); wheel.rotation.z=Math.PI/2; wheel.position.set(side*.91,.38,zz); group.add(wheel); }
  group.position.set(x,0,z); group.rotation.y=axis==='x'?(direction>0?Math.PI/2:-Math.PI/2):(direction>0?Math.PI:0);
  traffic.push({group,axis,direction,speed:rand(7,15)});
}
for(let i=0;i<24;i++) {
  const axis=Math.random()<.5?'x':'z',avenue=Math.floor(rand(-4,5))*50,direction=Math.random()<.5?1:-1,lane=avenue+(Math.random()<.5?-3.8:3.8);
  makeTrafficCar(axis==='x'?rand(-390,390):lane,axis==='z'?rand(-390,390):lane,axis,direction);
}
const checkpoints=[new THREE.Vector3(0,0,-92),new THREE.Vector3(96,0,-145),new THREE.Vector3(150,0,-54),new THREE.Vector3(51,0,43),new THREE.Vector3(-101,0,94)];
const checkpointGroup=new THREE.Group(); scene.add(checkpointGroup);
let checkpointIndex=0,money=12450,toastTimer=0;
function makeCheckpoint() {
  checkpointGroup.clear(); const p=checkpoints[checkpointIndex%checkpoints.length]; checkpointGroup.position.set(p.x,0,p.z);
  const ring=new THREE.Mesh(new THREE.TorusGeometry(4.5,.18,8,36),new THREE.MeshBasicMaterial({color:0xc9f16a})); ring.position.y=2.2; checkpointGroup.add(ring);
  const beam=new THREE.Mesh(new THREE.CylinderGeometry(.1,2.3,6,16,1,true),new THREE.MeshBasicMaterial({color:0xc9f16a,transparent:true,opacity:.18,side:THREE.DoubleSide,depthWrite:false})); beam.position.y=3; checkpointGroup.add(beam);
  const marker=new THREE.Mesh(new THREE.CylinderGeometry(.55,.55,.08,24),new THREE.MeshBasicMaterial({color:0xc9f16a})); marker.position.y=.04; checkpointGroup.add(marker);
  const light=new THREE.PointLight(0xc9f16a,14,24,2); light.position.y=2; checkpointGroup.add(light);
}
makeCheckpoint();
let started=false,paused=false,speed=0,heading=0,drift=0;
const keys=new Set(),touch=new Set(),carPosition=new THREE.Vector3();
function startGame(){started=true;paused=false;ui.intro.classList.add('hidden');ui.hud.classList.remove('hidden');ui.pauseScreen.classList.add('hidden');}
function togglePause(){if(!started)return;paused=!paused;ui.pauseScreen.classList.toggle('hidden',!paused);}
function resetCar(){carPosition.set(0,0,0);speed=0;heading=0;drift=0;car.position.copy(carPosition);car.rotation.set(0,0,0);}
ui.playBtn.addEventListener('click',startGame);
ui.pauseBtn.addEventListener('click',togglePause);ui.mobilePause.addEventListener('click',togglePause);ui.resumeBtn.addEventListener('click',togglePause);
window.addEventListener('keydown',e=>{
  if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();
  keys.add(e.key.toLowerCase()); if(e.key==='Escape'||e.key.toLowerCase()==='p')togglePause();
  if(e.key.toLowerCase()==='r')resetCar(); if(e.key==='Enter'&&!started)startGame();
});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
window.addEventListener('blur',()=>keys.clear());
for(const button of document.querySelectorAll('[data-control]')) {
  const control=button.dataset.control;
  const down=e=>{e.preventDefault();button.setPointerCapture?.(e.pointerId);touch.add(control);};
  const up=e=>{e.preventDefault();touch.delete(control);};
  button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('lostpointercapture',up);
}

